macro_rules! precise_macro_call_location {
    () => {
        fn precise_macro_call_location (ast : & MacroCallKind , db : & dyn HirDatabase ,) -> (InFile < SyntaxNodePtr > , Option < TextRange >) { match ast { MacroCallKind :: FnLike { ast_id , .. } => { let node = ast_id . to_node (db) ; (ast_id . with_value (SyntaxNodePtr :: from (AstPtr :: new (& node))) , node . path () . and_then (| it | it . segment ()) . and_then (| it | it . name_ref ()) . map (| it | it . syntax () . text_range ()) ,) } MacroCallKind :: Derive { ast_id , derive_attr_index , derive_index , .. } => { let node = ast_id . to_node (db) ; let token = (| | { let derive_attr = collect_attrs (& node) . nth (derive_attr_index . ast_index ()) . and_then (| x | Either :: left (x . 1)) ? ; let token_tree = derive_attr . meta () ? . token_tree () ? ; let chunk_by = token_tree . syntax () . children_with_tokens () . filter_map (| elem | match elem { syntax :: NodeOrToken :: Token (tok) => Some (tok) , _ => None , }) . chunk_by (| t | t . kind () == T ! [,]) ; let (_ , mut group) = chunk_by . into_iter () . filter (| & (comma , _) | ! comma) . nth (* derive_index as usize) ? ; group . find (| t | t . kind () == T ! [ident]) }) () ; (ast_id . with_value (SyntaxNodePtr :: from (AstPtr :: new (& node))) , token . as_ref () . map (| tok | tok . text_range ()) ,) } MacroCallKind :: Attr { ast_id , invoc_attr_index , .. } => { let node = ast_id . to_node (db) ; let attr = collect_attrs (& node) . nth (invoc_attr_index . ast_index ()) . and_then (| x | Either :: left (x . 1)) . unwrap_or_else (| | { panic ! ("cannot find attribute #{}" , invoc_attr_index . ast_index ()) }) ; (ast_id . with_value (SyntaxNodePtr :: from (AstPtr :: new (& attr))) , Some (attr . syntax () . text_range ()) ,) } } }
    };
}

precise_macro_call_location!()